// Đọc tệp 10 GB không thể nạp hết vào RAM: xử lý TỪNG MẢNH.
// Async generator mô phỏng đúng ý tưởng của stream.
async function* source() {
  for (const chunk of ["id,qty\n1,5\n2", ",7\n3,9\n"]) yield chunk;     // dữ liệu đến từng mảnh
}

// Ghép các mảnh thành dòng hoàn chỉnh (một dòng có thể bị cắt giữa hai mảnh)
async function* lines(chunks) {
  let rest = "";
  for await (const c of chunks) {
    rest += c;
    const parts = rest.split("\n");
    rest = parts.pop();                 // phần chưa trọn dòng, giữ lại
    for (const p of parts) yield p;
  }
  if (rest) yield rest;
}

(async () => {
  let total = 0;
  for await (const line of lines(source())) {
    if (line.startsWith("id")) continue;
    total += Number(line.split(",")[1]);
  }
  console.log(total);   // 21
})();

