async function* gen() { yield 1; yield 2; yield 3; }
async function* map(iter, fn) {
  for await (const x of iter) yield fn(x);
}
(async () => {
  const out = [];
  for await (const v of map(gen(), (x) => x * 10)) out.push(v);
  console.log(out.join(","));
})();

