async function* gen() { for (let i = 1; i <= 5; i++) yield i; }
async function* batch(iter, size) {
  let cur = [];
  for await (const x of iter) {
    cur.push(x);
    if (cur.length === size) { yield cur; cur = []; }
  }
  if (cur.length) yield cur;
}
(async () => {
  const out = [];
  for await (const b of batch(gen(), 2)) out.push(b);
  console.log(JSON.stringify(out));
})();
